#!/usr/bin/env node
/**
 * check:generated-derived — derived data is generated by the build, never hand-written.
 *
 * Five derived products come from the consumer's pins alone:
 *   icons       studio/generated/studio-icons.ts: one icon per pinned assets.icon-* slot, drawn
 *               from the glyph its pinned candidate carries (R-ICONS-FROM-PINS).
 *   provenance  studio/generated/studio-provenance.json: per assembled frame and section the
 *               data-clossys-slot/candidate/hash markers, from the page records and pins
 *               (R-PROVENANCE-GENERATED).
 *   uses        every slot.json `uses`: what the pinned candidate actually imports or
 *               references (R-USES-COMPUTED).
 *   brand       studio/generated/studio-brand.json: the workspace name and the mark, favicon,
 *               app icon, lockup and image, resolved from the consumer's pinned assets.* slots
 *               (R-BRAND-ONE).
 *   flow theme  studio/generated/studio-flow-theme.css: React Flow's --xy-* variables bound to
 *               the shadcn variables of the pinned themes.* tokens the pinned
 *               components.flow.canvas slot reads (R-PIPELINE-CANVAS).
 *
 * The check regenerates all five into a temp dir and fails on any difference with the committed
 * data, on any hand-written icon map, on any hand-typed provenance marker, and on any Foundry
 * brand path in consumer brand resolution.
 *
 *   node scripts/check-generated-derived.mjs            check; exit 1 with findings
 *   node scripts/check-generated-derived.mjs --write    write slot.json `uses` (the build step)
 *
 * Node builtins only: the generator imports these derivations, and the check runs on any tree.
 */
import { createHash } from 'node:crypto';
import { existsSync, mkdtempSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, relative, resolve, sep } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const producer = resolve(here, '..');
const repo = resolve(producer, '..', '..');
const AGENTS = ['director', 'designer', 'writer', 'publisher'];
// A registry item name (`button`, `card`) names a component first: shadcn registry dependencies are components.
const REF_LAYERS = ['components', 'sections', 'frames', 'assets', 'themes'];
const sha256 = bytes => createHash('sha256').update(bytes).digest('hex');
const object = value => typeof value === 'object' && value !== null && !Array.isArray(value);
const json = value => `${JSON.stringify(value, null, 2)}\n`;
const posix = path => path.split(sep).join('/');

/** Every slot folder of one agent: `agents/<agent>/<slot-id>/slot.json`. */
export function slotIds(clossysRoot, agent) {
  const dir = join(clossysRoot, 'agents', agent);
  if (!existsSync(dir)) return [];
  return readdirSync(dir).filter(name => existsSync(join(dir, name, 'slot.json'))).sort();
}

/** The pinned candidate of a slot, or undefined. A candidate whose bytes differ from its pin is not the pinned one. */
export function pinned(clossysRoot, agent, slot) {
  const dir = join(clossysRoot, 'agents', agent, slot);
  let pin;
  try { pin = JSON.parse(readFileSync(join(dir, 'pin.json'), 'utf8')); } catch { return undefined; }
  if (!object(pin) || typeof pin.candidate !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(pin.candidate)) return undefined;
  let raw;
  try { raw = readFileSync(join(dir, 'candidates', pin.candidate)); } catch { return undefined; }
  if (sha256(raw) !== pin.sha256) return undefined;
  const text = raw.toString('utf8');
  let item;
  if (pin.candidate.endsWith('.json')) try { item = JSON.parse(text); } catch { return undefined; }
  return { slot, agent, candidate: pin.candidate, sha256: pin.sha256, text, item };
}

// ---------------------------------------------------------------------------------------------
// 1. Icons (R-ICONS-FROM-PINS)

/** The lucide glyph a pinned icon candidate carries: its `clossys/assets.<slot>.json` glyph token. */
function iconGlyph(entry) {
  const name = entry.slot.slice('assets.'.length);
  for (const file of entry.item?.files ?? []) {
    if (!object(file) || typeof file.content !== 'string' || !String(file.path).endsWith('.json')) continue;
    let tokens; try { tokens = JSON.parse(file.content); } catch { continue; }
    const group = object(tokens) && object(tokens.assets) ? tokens.assets[name] : undefined;
    if (!object(group)) continue;
    for (const variant of ['default', ...Object.keys(group)]) {
      const token = group[variant];
      if (object(token) && token.$type === 'glyph' && Array.isArray(token.$value)) return token.$value;
    }
  }
  return undefined;
}

/** Each pinned assets.icon-* slot: its lucide name (from the pinned ref) and glyph. */
export function deriveIcons(clossysRoot) {
  const rows = [], findings = [];
  for (const slot of slotIds(clossysRoot, 'designer').filter(id => id.startsWith('assets.icon-'))) {
    const entry = pinned(clossysRoot, 'designer', slot);
    if (!entry) continue;
    const ref = (entry.item?.meta?.source?.ref ?? []).find(value => typeof value === 'string' && value.startsWith('lucide/'));
    const lucide = ref ? /^lucide\/([a-z0-9-]+)@/.exec(ref)?.[1] : undefined;
    const glyph = iconGlyph(entry);
    if (!lucide || !glyph) { findings.push({ rule: 'R-ICONS-FROM-PINS', file: `clossys/agents/designer/${slot}`, detail: 'pinned icon candidate carries no lucide ref or glyph' }); continue; }
    rows.push({ slot, lucide, candidate: entry.candidate, sha256: entry.sha256, glyph });
  }
  return { rows, findings };
}

/** studio/generated/studio-icons.ts: one lucide icon per pinned icon slot, built from the pinned glyph. */
export function iconsModule(clossysRoot) {
  const { rows } = deriveIcons(clossysRoot);
  return `// Generated from each pinned assets.icon-* candidate's glyph. Run npm run generate:studio-map.
import { createLucideIcon, type LucideIcon } from 'lucide-react';

/** The icon per pinned icon slot, drawn from the glyph the pinned candidate carries. */
export const STUDIO_ICONS: Readonly<Record<string, LucideIcon>> = {
${rows.map(row => `  ${JSON.stringify(row.slot)}: createLucideIcon(${JSON.stringify(row.lucide)}, ${JSON.stringify(row.glyph)}),`).join('\n')}
};

/** Where each icon came from: the pinned lucide icon, candidate file and content hash. */
export const STUDIO_ICON_SOURCES: Readonly<Record<string, { lucide: string; candidate: string; hash: string }>> = {
${rows.map(row => `  ${JSON.stringify(row.slot)}: ${JSON.stringify({ lucide: row.lucide, candidate: row.candidate, hash: `sha256:${row.sha256}` })},`).join('\n')}
};
`;
}

// ---------------------------------------------------------------------------------------------
// 2. Provenance (R-PROVENANCE-GENERATED)

/** studio/generated/studio-provenance.json: the DOM markers per assembled section, from its binding. */
export function provenanceJson(rows) {
  const out = {};
  for (const row of rows) out[row.slot] = { 'data-clossys-slot': row.slot, 'data-clossys-candidate': row.candidate, 'data-clossys-hash': `sha256:${row.sha256}` };
  return json(out);
}

/** The pinned frames and sections the Studio page records assemble (studio-map.json items), with their pins. */
export function studioSectionPins(clossysRoot, studioMapPath = join(producer, 'studio', 'generated', 'studio-map.json')) {
  const projection = JSON.parse(readFileSync(studioMapPath, 'utf8'));
  return (projection.items ?? []).filter(item => /^(?:frames|sections)\./.test(item.slot)).map(item => {
    const entry = pinned(clossysRoot, 'designer', item.slot);
    if (!entry) throw new Error(`${item.slot} has no intact pin`);
    return { slot: item.slot, candidate: entry.candidate, sha256: entry.sha256 };
  });
}

// ---------------------------------------------------------------------------------------------
// 3. Uses (R-USES-COMPUTED)

const kebab = name => name.replace(/Icon$/, '').replace(/([a-z0-9])([A-Z])/g, '$1-$2').replace(/([A-Za-z])([0-9])/g, '$1-$2').toLowerCase();

/** `writer:x.y@2`, `button`, `@scope/registry/components.x` -> a known slot id. */
function toSlotId(ref, known) {
  const bare = ref.replace(/^[a-z]+:/, '').replace(/@\d+$/, '').replace(/^.*\//, '');
  if (known.has(bare)) return bare;
  for (const layer of REF_LAYERS) if (known.has(`${layer}.${bare}`)) return `${layer}.${bare}`;
  return undefined;
}

/** Every module specifier and named binding one source file imports or re-exports. */
export function importsOf(source) {
  const out = [];
  const pattern = /(?:^|[\n;])\s*(?:import|export)\s+(?:type\s+)?([\s\S]*?)\s*from\s*['"]([^'"]+)['"]|(?:^|[\n;])\s*import\s*['"]([^'"]+)['"]/g;
  for (const match of source.matchAll(pattern)) {
    if (match[3]) { out.push({ spec: match[3], names: [] }); continue; }
    const clause = match[1] ?? '';
    const named = /\{([\s\S]*?)\}/.exec(clause)?.[1] ?? '';
    const names = named.split(',').map(part => part.trim().replace(/^type\s+/, '').split(/\s+as\s+/)[0].trim()).filter(Boolean);
    out.push({ spec: match[2], names });
  }
  return out;
}

/** Export name -> component file stem for the Designer UI package (`@clossys/designer-ui`). */
function designerUiExports(root = repo) {
  const dir = join(root, 'packages', 'designer', 'ui', 'src', 'components', 'ui');
  const map = new Map();
  if (!existsSync(dir)) return map;
  for (const file of readdirSync(dir).filter(name => /\.tsx?$/.test(name) && !/\.test\./.test(name)).sort()) {
    const stem = file.replace(/\.tsx?$/, '');
    const text = readFileSync(join(dir, file), 'utf8');
    for (const block of text.matchAll(/export\s*\{([\s\S]*?)\}/g)) for (const part of block[1].split(',')) {
      const name = part.trim().replace(/^type\s+/, '').split(/\s+as\s+/).pop().trim();
      if (name && !map.has(name)) map.set(name, stem);
    }
    for (const decl of text.matchAll(/export\s+(?:default\s+)?(?:function|const|class)\s+([A-Za-z0-9_]+)/g)) if (!map.has(decl[1])) map.set(decl[1], stem);
  }
  return map;
}

/** Writer copy key -> the pinned writer slot defining it. */
function writerKeys(clossysRoot) {
  const map = new Map();
  for (const slot of slotIds(clossysRoot, 'writer')) {
    const entry = pinned(clossysRoot, 'writer', slot);
    if (!entry) continue;
    for (const match of entry.text.matchAll(/<!--\s*(\{[\s\S]*?\})\s*-->/g)) {
      let record; try { record = JSON.parse(match[1]); } catch { continue; }
      if (typeof record?.id === 'string' && !map.has(record.id)) map.set(record.id, slot);
    }
  }
  return map;
}

/** Every string anywhere in a JSON value. */
function strings(value, out = []) {
  if (typeof value === 'string') out.push(value);
  else if (Array.isArray(value)) for (const entry of value) strings(entry, out);
  else if (object(value)) for (const entry of Object.values(value)) strings(entry, out);
  return out;
}

/** The computed `uses` of every slot, keyed `<agent>/<slot>`: what its pinned candidate imports or references. */
export function deriveUses(clossysRoot, root = repo) {
  const known = new Set(AGENTS.flatMap(agent => slotIds(clossysRoot, agent)));
  const ui = designerUiExports(root);
  const keys = writerKeys(clossysRoot);
  const pins = new Map();
  for (const agent of AGENTS) for (const slot of slotIds(clossysRoot, agent)) pins.set(`${agent}/${slot}`, pinned(clossysRoot, agent, slot));
  // Lucide icon name -> pinned icon slot; pinned element name -> slot (sibling section imports).
  const lucide = new Map(), elements = new Map();
  for (const [key, entry] of pins) {
    if (!entry?.item || !key.startsWith('designer/')) continue;
    const ref = (entry.item.meta?.source?.ref ?? []).find(value => typeof value === 'string' && value.startsWith('lucide/'));
    const name = ref ? /^lucide\/([a-z0-9-]+)@/.exec(ref)?.[1] : undefined;
    if (name && entry.slot.startsWith('assets.icon-') && !lucide.has(name)) lucide.set(name, entry.slot);
    if (typeof entry.item.name === 'string' && !elements.has(entry.item.name)) elements.set(entry.item.name, entry.slot);
  }
  const uses = new Map();
  for (const [key, entry] of pins) {
    const [agent, slot] = key.split('/');
    const out = new Set();
    const add = id => { if (id && id !== slot && known.has(id)) out.add(id); };
    if (entry?.item && agent === 'designer') {
      const item = entry.item;
      for (const ref of strings(item.registryDependencies ?? [])) add(toSlotId(ref, known));
      for (const ref of strings([item.meta?.element?.deps?.registry ?? [], item.meta?.element?.deps?.elements ?? []])) add(toSlotId(ref, known));
      for (const file of item.files ?? []) {
        if (!object(file) || typeof file.content !== 'string') continue;
        if (String(file.path).endsWith('registry-item.json')) {
          try { for (const ref of strings(JSON.parse(file.content).registryDependencies ?? [])) add(toSlotId(ref, known)); } catch { /* not JSON */ }
          continue;
        }
        if (!/\.(?:tsx?|jsx?|mjs)$/.test(String(file.path))) continue;
        for (const { spec, names } of importsOf(file.content)) {
          const ui1 = /^@\/(?:registry\/[^/]+\/)?components\/ui\/([a-z0-9-]+)$/.exec(spec)?.[1];
          if (ui1) add(`components.${ui1}`);
          else if (spec === '@clossys/designer-ui') for (const name of names) { const stem = ui.get(name); if (stem) add(`components.${stem}`); }
          else if (spec === 'lucide-react') for (const name of names) add(lucide.get(kebab(name)));
          else if (/^\.\.\/[a-z0-9-]+$/.test(spec)) add(elements.get(spec.slice(3)));
        }
      }
    } else if (entry?.item && agent === 'publisher') {
      // A page or publication record references slots (frame, sections, modules, pages, icons) and Writer copy keys.
      for (const value of strings(entry.item)) {
        if (known.has(value)) add(value);
        else if (keys.has(value)) add(keys.get(value));
      }
    }
    uses.set(key, [...out].sort());
  }
  return uses;
}

/** `uses` as one JSON document keyed `<agent>/<slot>`, for a temp-dir diff. */
export function usesJson(uses) { return json(Object.fromEntries([...uses].sort(([a], [b]) => a.localeCompare(b)))); }

/** The `uses` committed in every slot.json, in the same shape. */
export function committedUses(clossysRoot) {
  const out = new Map();
  for (const agent of AGENTS) for (const slot of slotIds(clossysRoot, agent)) {
    const doc = JSON.parse(readFileSync(join(clossysRoot, 'agents', agent, slot, 'slot.json'), 'utf8'));
    out.set(`${agent}/${slot}`, Array.isArray(doc.uses) ? doc.uses : []);
  }
  return out;
}

/** Write computed `uses` into each slot.json, keeping every other byte of the document. */
export function writeUses(clossysRoot, uses = deriveUses(clossysRoot)) {
  let changed = 0;
  for (const [key, list] of uses) {
    const [agent, slot] = key.split('/');
    const path = join(clossysRoot, 'agents', agent, slot, 'slot.json');
    const text = readFileSync(path, 'utf8');
    const doc = JSON.parse(text);
    if (JSON.stringify(doc.uses) === JSON.stringify(list)) continue;
    doc.uses = list;
    writeFileSync(path, json(doc));
    changed++;
  }
  return changed;
}

// ---------------------------------------------------------------------------------------------
// 4. Brand (R-BRAND-ONE)

const safeSvg = value => {
  const svg = typeof value === 'string' ? value.trim() : '';
  return svg.startsWith('<svg') && svg.endsWith('</svg>') && !/<script|\son[a-z]+=|javascript:|<foreignObject/i.test(svg) ? svg : undefined;
};

/** The pinned design tokens of `assets.<name>`, or undefined. */
function assetTokens(clossysRoot, name) {
  const entry = pinned(clossysRoot, 'designer', `assets.${name}`);
  for (const file of entry?.item?.files ?? []) {
    if (!object(file) || typeof file.content !== 'string' || !String(file.path).endsWith('.json')) continue;
    let tokens; try { tokens = JSON.parse(file.content); } catch { continue; }
    const group = object(tokens) && object(tokens.assets) ? tokens.assets[name] : undefined;
    if (object(group)) return { entry, group };
  }
  return undefined;
}

/** One asset variant's SVG, following `{{assets.<name>.<variant>}}` aliases inside the consumer's own pins. */
function variantSvg(clossysRoot, name, variant, seen = new Set()) {
  const key = `${name}.${variant}`;
  if (seen.has(key)) return undefined;
  seen.add(key);
  const token = assetTokens(clossysRoot, name)?.group[variant];
  const value = object(token) ? token.$value : undefined;
  const alias = typeof value === 'string' ? /^\{\{assets\.([a-z0-9-]+)\.([a-z0-9-]+)\}\}$/.exec(value.trim()) : undefined;
  return alias ? variantSvg(clossysRoot, alias[1], alias[2], seen) : safeSvg(value);
}

/** The image rule's SVG (an SVG data URI). */
function imageSvg(clossysRoot, variant) {
  const token = assetTokens(clossysRoot, 'image')?.group[variant];
  const src = object(token) && object(token.$value) ? token.$value.src : undefined;
  const base64 = typeof src === 'string' ? /^data:image\/svg\+xml;base64,([A-Za-z0-9+/]+={0,2})$/.exec(src)?.[1] : undefined;
  return base64 ? safeSvg(Buffer.from(base64, 'base64').toString('utf8')) : undefined;
}

/** The consumer brand: name, mark, favicon, app icon, lockup and image, from its own pinned assets.* slots. */
export function deriveBrand(clossysRoot) {
  const svg = (name, ...variants) => { for (const variant of variants) { const value = variantSvg(clossysRoot, name, variant); if (value) return value; } return undefined; };
  const markLight = svg('mark', 'positive', 'mono');
  const lockupLight = svg('lockup', 'positive');
  const resolved = {
    mark: markLight ? { light: markLight, dark: svg('mark', 'reversed') ?? markLight } : undefined,
    favicon: svg('favicon', 'vector', 'raster'),
    appIcon: svg('app-icon', 'maskable', 'standard'),
    lockup: lockupLight ? { light: lockupLight, dark: svg('lockup', 'reversed') ?? lockupLight } : undefined,
    image: { default: imageSvg(clossysRoot, 'default'), placeholder: imageSvg(clossysRoot, 'placeholder') },
  };
  const name = /\baria-label="([^"<>]{1,80})"/.exec(markLight ?? lockupLight ?? '')?.[1];
  const sources = {};
  for (const asset of ['mark', 'favicon', 'app-icon', 'lockup', 'image']) {
    const entry = pinned(clossysRoot, 'designer', `assets.${asset}`);
    if (entry) sources[`assets.${asset}`] = { candidate: entry.candidate, hash: `sha256:${entry.sha256}` };
  }
  return { name, sources, resolved };
}

/** studio/generated/studio-brand.json: the resolved brand's name, pinned sources and the hash of each resolved file. */
export function brandJson(clossysRoot) {
  const { name, sources, resolved } = deriveBrand(clossysRoot);
  const digest = value => (typeof value === 'string' ? `sha256:${sha256(value)}` : object(value) ? Object.fromEntries(Object.entries(value).map(([key, entry]) => [key, digest(entry)])) : null);
  return json({ name: name ?? null, sources, files: digest(resolved) });
}

// ---------------------------------------------------------------------------------------------
// 5. Flow theme (R-PIPELINE-CANVAS)

/** Which pinned token each React Flow variable takes: xyflow's documented --xy-* names, each bound to one themes.* slot. */
const XY_FROM_THEMES = [
  ['--xy-background-color', 'themes.background'],
  ['--xy-node-background-color', 'themes.card'],
  ['--xy-node-color', 'themes.card-foreground'],
  ['--xy-node-border', 'themes.border', value => `1px solid ${value}`],
  ['--xy-node-border-radius', 'themes.radius'],
  ['--xy-edge-stroke', 'themes.muted-foreground'],
  ['--xy-edge-stroke-selected', 'themes.ring'],
  ['--xy-handle-background-color', 'themes.secondary'],
  ['--xy-handle-border-color', 'themes.border'],
  ['--xy-attribution-background-color', 'themes.background'],
  // The stock Controls and MiniMap, so both follow the theme (light and dark) instead of xyflow's light defaults.
  ['--xy-controls-button-background-color', 'themes.card'],
  ['--xy-controls-button-background-color-hover', 'themes.accent'],
  ['--xy-controls-button-color', 'themes.card-foreground'],
  ['--xy-controls-button-color-hover', 'themes.accent-foreground'],
  ['--xy-controls-button-border-color', 'themes.border'],
  // The MiniMap reads in both modes: steps in the muted foreground on the card, the area outside the
  // view dimmed by a tint of that foreground, the view outlined in the ring colour.
  ['--xy-minimap-background-color', 'themes.card'],
  ['--xy-minimap-node-background-color', 'themes.muted-foreground'],
  ['--xy-minimap-node-stroke-color', 'themes.card'],
  ['--xy-minimap-mask-background-color', 'themes.muted-foreground', value => `color-mix(in oklab, ${value} 18%, transparent)`],
  ['--xy-minimap-mask-stroke-color', 'themes.ring'],
];

/**
 * React Flow's theme variables from the pinned tokens: each themes.* slot must be pinned and read
 * by the pinned components.flow.canvas contract; its shadcn variable is the one its pinned
 * candidate emits (cssVars.light).
 */
export function deriveFlowTheme(clossysRoot) {
  const findings = [];
  const canvas = 'components.flow.canvas';
  let reads = [];
  try { reads = JSON.parse(readFileSync(join(clossysRoot, 'agents', 'designer', canvas, 'slot.json'), 'utf8')).contract?.allowedReads?.themes ?? []; }
  catch { findings.push({ rule: 'R-PIPELINE-CANVAS', file: `clossys/agents/designer/${canvas}/slot.json`, detail: 'flow canvas slot is missing' }); }
  if (!pinned(clossysRoot, 'designer', canvas)) findings.push({ rule: 'R-PIPELINE-CANVAS', file: `clossys/agents/designer/${canvas}/pin.json`, detail: 'flow canvas is not pinned' });
  const rows = [];
  for (const [name, slot, format = value => value] of XY_FROM_THEMES) {
    const file = `clossys/agents/designer/${slot}/pin.json`;
    if (!reads.includes(slot)) { findings.push({ rule: 'R-PIPELINE-CANVAS', file, detail: `${canvas} does not read ${slot}` }); continue; }
    const pin = pinned(clossysRoot, 'designer', slot);
    const vars = Object.keys(pin?.item?.cssVars?.light ?? {});
    if (!pin || vars.length !== 1) { findings.push({ rule: 'R-PIPELINE-CANVAS', file, detail: `${slot} is not pinned with one shadcn variable` }); continue; }
    rows.push({ name, value: format(`var(--${vars[0]})`), source: `${slot} ${pin.candidate}` });
  }
  return { rows, findings };
}

/** studio/generated/studio-flow-theme.css: the --xy-* variables on React Flow's root, from deriveFlowTheme. */
export function flowThemeCss(clossysRoot) {
  const { rows } = deriveFlowTheme(clossysRoot);
  return `/* Generated by the Producer build from the pinned themes.* tokens components.flow.canvas reads. Do not edit. */\n.react-flow {\n${rows.map(row => `  ${row.name}: ${row.value}; /* ${row.source} */`).join('\n')}\n}\n`;
}

// ---------------------------------------------------------------------------------------------
// Static rules: nothing derived is hand-written.

function walk(dir, out = []) {
  if (!existsSync(dir)) return out;
  for (const name of readdirSync(dir).sort()) {
    if (name === 'node_modules' || name === 'generated' || name === '.next') continue;
    const path = join(dir, name);
    if (statSync(path).isDirectory()) walk(path, out);
    else if (/\.(?:tsx?|mjs|cjs|js)$/.test(name) && !/\.test\./.test(name)) out.push(path);
  }
  return out;
}
const lineOf = (text, index) => text.slice(0, index).split('\n').length;

export function staticFindings(root = repo) {
  const findings = [];
  const studio = join(root, 'packages', 'producer', 'studio');
  const files = walk(studio).filter(file => !posix(relative(studio, file)).startsWith('checks/'));
  for (const file of files) {
    const text = readFileSync(file, 'utf8'), rel = posix(relative(root, file));
    // An object keyed by icon slot ids, outside the generated map, is a hand-written icon map.
    for (const match of text.matchAll(/['"]assets\.icon-[a-z0-9-]+['"]\s*:/g)) findings.push({ rule: 'R-ICONS-FROM-PINS', file: `${rel}:${lineOf(text, match.index)}`, detail: 'hand-written icon map entry' });
    // A hand-typed provenance attribute on a rendered element.
    if (/\.[jt]sx$/.test(file)) for (const match of text.matchAll(/\sdata-(?:studio-section|clossys-(?:slot|candidate|hash))=(?:["']|\{\s*["'`])/g)) findings.push({ rule: 'R-PROVENANCE-GENERATED', file: `${rel}:${lineOf(text, match.index)}`, detail: 'hand-typed provenance marker' });
  }
  const icons = join(studio, 'lib', 'studio-icons.tsx');
  if (existsSync(icons) && !/from ['"]\.\.\/generated\/studio-icons['"]/.test(readFileSync(icons, 'utf8'))) findings.push({ rule: 'R-ICONS-FROM-PINS', file: posix(relative(root, icons)), detail: 'Studio icons do not read the generated icon map' });
  // Consumer brand resolution never reaches Foundry's own mark, nor the old-store cells.
  const resolution = [
    ...['index.ts', 'designer-globals.ts', 'default-avatar.ts', 'consumer-brand.ts'].map(name => join(root, 'packages', 'producer', 'src', 'server', name)).filter(existsSync),
    ...['app', 'lib', 'frames', 'components'].flatMap(dir => walk(join(studio, dir))),
  ];
  for (const file of resolution) {
    const text = readFileSync(file, 'utf8'), rel = posix(relative(root, file));
    for (const match of text.matchAll(/studio-mark(?:\.svg)?/g)) findings.push({ rule: 'R-BRAND-ONE', file: `${rel}:${lineOf(text, match.index)}`, detail: 'Foundry brand path in consumer brand resolution' });
    const brand = /export async function consumerBrand[\s\S]*?\n\}/.exec(text);
    if (brand && /readCells\(/.test(brand[0])) findings.push({ rule: 'R-BRAND-ONE', file: `${rel}:${lineOf(text, brand.index)}`, detail: 'consumer brand resolves from old-store cells, not pinned assets.* slots' });
  }
  return findings;
}

// ---------------------------------------------------------------------------------------------

/** Regenerate all five products into a temp dir and compare with the committed data. */
export function checkGeneratedDerived({ root = repo, clossysRoot = join(root, 'clossys') } = {}) {
  const findings = [];
  const generated = join(root, 'packages', 'producer', 'studio', 'generated');
  const temp = mkdtempSync(join(tmpdir(), 'generated-derived-'));
  const products = {};
  const icons = deriveIcons(clossysRoot);
  findings.push(...icons.findings);
  products['studio-icons.ts'] = iconsModule(clossysRoot);
  try { products['studio-provenance.json'] = provenanceJson(studioSectionPins(clossysRoot, join(generated, 'studio-map.json'))); }
  catch (error) { findings.push({ rule: 'R-PROVENANCE-GENERATED', file: 'packages/producer/studio/generated/studio-map.json', detail: error.message }); }
  products['studio-brand.json'] = brandJson(clossysRoot);
  findings.push(...deriveFlowTheme(clossysRoot).findings);
  products['studio-flow-theme.css'] = flowThemeCss(clossysRoot);
  const rules = { 'studio-icons.ts': 'R-ICONS-FROM-PINS', 'studio-provenance.json': 'R-PROVENANCE-GENERATED', 'studio-brand.json': 'R-BRAND-ONE', 'studio-flow-theme.css': 'R-PIPELINE-CANVAS' };
  for (const [name, content] of Object.entries(products)) {
    writeFileSync(join(temp, name), content);
    const path = join(generated, name);
    const stored = existsSync(path) ? readFileSync(path, 'utf8') : undefined;
    if (stored === undefined) findings.push({ rule: rules[name], file: posix(relative(root, path)), detail: 'generated file is missing' });
    else if (stored !== content) findings.push({ rule: rules[name], file: posix(relative(root, path)), detail: `differs from the regenerated copy (${join(temp, name)})` });
  }
  // Provenance reaches the DOM through the generated assembly bindings, not hand-typed folder markers.
  const bindings = join(generated, 'assembly-bindings.ts');
  if (!existsSync(bindings) || !/from ['"]\.\/studio-provenance\.json['"]/.test(readFileSync(bindings, 'utf8'))) findings.push({ rule: 'R-PROVENANCE-GENERATED', file: posix(relative(root, bindings)), detail: 'assembly bindings do not apply the generated provenance markers' });
  // Every bound frame and section receives its markers: a bare `"<slot>": FrameN,` / `SectionN,` binding drops them.
  else for (const [, slot] of readFileSync(bindings, 'utf8').matchAll(/^\s*"((?:frames|sections)\.[^"]+)": (?!marked\()/gm)) findings.push({ rule: 'R-PROVENANCE-GENERATED', file: posix(relative(root, bindings)), detail: `${slot} is bound without its generated provenance markers` });
  const uses = deriveUses(clossysRoot, root);
  writeFileSync(join(temp, 'uses.json'), usesJson(uses));
  const committed = committedUses(clossysRoot);
  for (const [key, list] of uses) {
    const stored = committed.get(key) ?? [];
    if (JSON.stringify(stored) !== JSON.stringify(list)) findings.push({ rule: 'R-USES-COMPUTED', file: `clossys/agents/${key}/slot.json`, detail: `uses ${JSON.stringify(stored)} != computed ${JSON.stringify(list)}` });
  }
  findings.push(...staticFindings(root));
  return { findings, temp };
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  const args = process.argv.slice(2);
  // Run from the repository root of whatever tree holds this script (head or a base export).
  if (args.includes('--write')) {
    const changed = writeUses(join(repo, 'clossys'));
    console.log(`check-generated-derived: wrote computed uses into ${changed} slot.json file(s)`);
  } else {
    const { findings, temp } = checkGeneratedDerived();
    for (const finding of findings) console.log(`${finding.rule} ${finding.file}: ${finding.detail}`);
    const counts = {};
    for (const finding of findings) counts[finding.rule] = (counts[finding.rule] ?? 0) + 1;
    console.log(`check-generated-derived: ${findings.length} finding(s)${findings.length ? ` ${JSON.stringify(counts)}` : ''}; regenerated into ${temp}`);
    process.exitCode = findings.length ? 1 : 0;
  }
}
